    46   /* This is not an ERR message, the connection is not closed afterwards */
    47  static UA_StatusCode
    48  sendServiceFault(UA_SecureChannel *channel, const UA_ByteString *msg,
    49                   size_t offset, const UA_DataType *responseType,
    50                   UA_UInt32 requestId, UA_StatusCode error) {
    51      UA_RequestHeader requestHeader;
    52      UA_StatusCode retval = UA_RequestHeader_decodeBinary(msg, &offset, &requestHeader);
    53      if(retval != UA_STATUSCODE_GOOD)
    54          return retval;
    55      void *response = UA_alloca(responseType->memSize);
    56      UA_init(response, responseType);
    57      UA_ResponseHeader *responseHeader = (UA_ResponseHeader*)response;
    58      responseHeader->requestHandle = requestHeader.requestHandle;
    59      responseHeader->timestamp = UA_DateTime_now();
    60      responseHeader->serviceResult = error;
    61
    62      // Send error message. Message type is MSG and not ERR, since we are on a securechannel!
    63      retval = UA_SecureChannel_sendSymmetricMessage(channel, requestId, UA_MESSAGETYPE_MSG,
    64                                                     response, responseType);
    65
    66      UA_RequestHeader_deleteMembers(&requestHeader);
    67      UA_LOG_DEBUG(channel->securityPolicy->logger, UA_LOGCATEGORY_SERVER,
    68                   "Sent ServiceFault with error code %s", UA_StatusCode_name(error));
    69      return retval;
    70  }
