   275      connection->remoteConf.maxMessageSize = helloMessage.maxMessageSize; /* zero -> unlimited */
   276      connection->remoteConf.protocolVersion = helloMessage.protocolVersion;
   277      connection->remoteConf.recvBufferSize = helloMessage.receiveBufferSize;
   278      if(connection->localConf.sendBufferSize > helloMessage.receiveBufferSize)
   279          connection->localConf.sendBufferSize = helloMessage.receiveBufferSize;
   280      connection->remoteConf.sendBufferSize = helloMessage.sendBufferSize;
