  1493  UA_decodeBinary(const UA_ByteString *src, size_t *offset, void *dst,
  1494                  const UA_DataType *type, size_t customTypesSize,
  1495                  const UA_DataType *customTypes) {
  1496      /* Set up the context */
  1497      Ctx ctx;
  1498      ctx.pos = &src->data[*offset];
  1499      ctx.end = &src->data[src->length];
  1500      ctx.depth = 0;
  1501      ctx.customTypesArraySize = customTypesSize;
  1502      ctx.customTypesArray = customTypes;
  1503
  1504      /* Decode */
  1505      memset(dst, 0, type->memSize); /* Initialize the value */
  1506      status ret = decodeBinaryInternal(dst, type, &ctx);
  1507
  1508      if(ret == UA_STATUSCODE_GOOD) {
  1509          /* Set the new offset */
  1510          *offset = (size_t)(ctx.pos - src->data) / sizeof(u8);
  1511      } else {
  1512          /* Clean up */
  1513          UA_deleteMembers(dst, type);
  1514          memset(dst, 0, type->memSize);
  1515      }
  1516      return ret;
  1517  }
